import java.io.BufferedInputStream
import java.io.BufferedOutputStream
import java.io.InputStream
import java.io.PrintStream
import java.util.StringTokenizer
import kotlin.math.min

class Solution : Helper() {
    fun __main(_TCID: Int = 1) {
        readWordString()
        val s = readWordString().toCharArray()
        val n = s.size
        val upb = n - 1

        val res = ValueRefPointer<Long>()
        res.valueNullable = n.toLong()
        seq(1L, upb.toLong()).takeWhile { i ->
            countLength(0L, i - 1) <= countLength(i, upb.toLong())
        }.elect { i ->
            val leftLen = countLength(0L, i - 1).toInt()
            val rightEnd = getRight(i, leftLen.toLong()).toInt()
            val leftSeq = (0 until leftLen).map { s[it] }
            val rightSeq = (i.toInt()..rightEnd).map { s[it] }
            if (leftSeq == rightSeq) {
                val v = 1L + i + (n - i.toInt() - leftLen)
                res.updateCompute(v) { a, b -> min(a, b) }
            }
        }
        writeNumber(res.valueNullable ?: 1L)
        writeLine()
    }
}

