            }
            out.flush()
        }

        private fun read(): Int {
            return input.read()
        }

        private fun isWhitespace(c: Char): Boolean {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t'
        }

        @JvmStatic
        fun readWordString(): String {
            val sb = StringBuilder()
            var c = read()
            while (c >= 0 && isWhitespace(c.toChar())) {
                c = read()
            }
            if (c < 0) throw java.io.EOFException()
            while (c >= 0 && !isWhitespace(c.toChar())) {
                sb.append(c.toChar())
                c = read()
            }
            return sb.toString()
        }

        @JvmStatic
        fun readLong64(): Long = readWordString().toLong()

        @JvmStatic
        fun readSingleChar(): Char {
            var c = read()
            while (c >= 0 && isWhitespace(c.toChar())) {
                c = read()
            }
            if (c < 0) throw java.io.EOFException()
            return c.toChar()
        }

        @JvmStatic
        fun seq(low: Long, high: Long, skip: Int = 1): Sequence<Long> = sequence {
            var i = low
            while (i <= high) {
                yield(i)
                i += skip
            }
        }

        @JvmStatic
        fun rev(low: Long, high: Long, skipPositive: Int = 1): Sequence<Long> = sequence {
            var i = high
