        @JvmStatic
        fun <T> collect(vararg elemS: T): Array<out T> = elemS

        @JvmStatic
        fun <T : Any> optional(hasValue: Boolean, value: T): T? = if (hasValue) value else null

        @JvmStatic
        fun <T> identity(obj: T): T = obj

