            }
        }

        @JvmStatic
        fun <T> assert(actual: T, expected: T) {
            if (actual != expected) {
                assert(false)
            }
        }

        @JvmStatic
        fun <T> ll(emptyExample: T): MutableList<T> = mutableListOf()

        @JvmStatic
        fun <T : Any> optional(hasValue: Boolean, calc: () -> T): T? = if (hasValue) calc() else null

