    fun writeLine() {
        Companion.out.println()
    }

    fun writeSeparator() {
        val s = separatorAutoString
        if (!s.isNullOrEmpty()) {
            Companion.out.print(s)
        }
    }

    fun writeText(c: Char) {
        Companion.out.print(c)
        writeSeparator()
    }

    fun writeText(s: String) {
