        writeSeparator()
    }

    class ValueRefPointer<T : Any> {
        var valueNullable: T? = null

        fun ifAbsent(init: (ValueRefPointer<T>) -> Unit): ValueRefPointer<T> {
            if (valueNullable == null) init(this)
            return this
        }

        fun updateIfAbsent(calc: () -> T): ValueRefPointer<T> {
            if (valueNullable == null) valueNullable = calc()
            return this
        }

        fun updateCompute(other: T, merge_CHECKED: (T, T) -> T): ValueRefPointer<T> {
            var ans = other
            val v = valueNullable
            if (v != null) ans = merge_CHECKED(other, v)
            valueNullable = ans
            return this
        }

        fun updateCompute(other: T?, merge_CHECKED: (T, T) -> T): ValueRefPointer<T> {
            if (other != null) updateCompute(other, merge_CHECKED)
            return this
        }

        fun swap(with: ValueRefPointer<T>): ValueRefPointer<T> {
            val temp = valueNullable
            valueNullable = with.valueNullable
            with.valueNullable = temp
            return this
        }

        fun updateCompute(other: ValueRefPointer<T>, merge_CHECKED: (T, T) -> T): ValueRefPointer<T> {
            return updateCompute(other.valueNullable, merge_CHECKED)
        }

        override fun toString(): String = valueNullable.toString()
    }
}

object Extension {
    fun <T> Sequence<T>.elect(act: (T) -> Unit): Sequence<T> {
        for (elem in this) act(elem)
        return this
    }

    fun <T> Long.select(getter: () -> T): Sequence<T> = sequence {
        var count = this@select
        while (count-- > 0) {
            yield(getter())
        }
    }

    fun Long.elect(act: () -> Unit) {
        var count = this
        while (count-- > 0) act()
    }

    fun <T> Iterable<T>.toKvpList(): List<Pair<Int, T>> =
        this.mapIndexed { idx, elem -> Pair(idx, elem) }

    fun <T> Iterable<Long>.selectElement(lst: List<T>): List<T> =
        this.map { lst[it.toInt()] }

    fun Long.int32(): Int = this.toInt()

    fun Int.long64(): Long = this.toLong()

    fun <T : Any> T.optional(): T? = this

    fun <T : Any> Iterable<T>.optional(): Iterable<T?> = this.map { it.optional() }

    fun Long.skip(skipSigned: Long): Long = this + skipSigned

    fun <T : Any> Iterable<T>.aggregateOrNullable(merge_CHECKED: (T, T) -> T): T? {
        val it = iterator()
        if (!it.hasNext()) return null
        var res = it.next()
        while (it.hasNext()) {
            res = merge_CHECKED(res, it.next())
        }
        return res
    }

    fun sumLong64(stream: Iterable<Int>): Long = stream.fold(0L) { acc, x -> acc + x }

    fun Int.explainSearchIndex(): Int? = if (this < 0) null else this

    fun <T> Iterable<T>.ll(): Array<T> = this.toList().toTypedArray()

    fun <T : Comparable<T>> Array<T>.sort(): Array<T> {
        this.sort()
        return this
    }

    fun <T : Comparable<T>> MutableList<T>.sortList(): MutableList<T> {
        this.sort()
        return this
    }

    fun <T> List<T>.getUpperBound(): Int = this.size - 1

    fun <T : Any> List<T>.elementAtOrNullable(index: Int): T? =
        if (index < 0 || index >= this.size) null else this[index]

    fun Iterable<Char>.stringify(): String = this.joinToString(separator = "")
}

