class FastScanner(private val input: InputStream) {
    private val bufferSize = 1 shl 16
    private val buffer = ByteArray(bufferSize)
    private var len = 0
    private var ptr = 0

    private fun readByte(): Int {
        if (ptr >= len) {
            len = input.read(buffer)
            ptr = 0
            if (len <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun next(): String {
        val sb = StringBuilder()
        var c = readByte()
        while (c != -1 && Helper.isWhitespace(c.toChar())) {
            c = readByte()
        }
        if (c == -1) Helper.EOF()
        while (c != -1 && !Helper.isWhitespace(c.toChar())) {
            sb.append(c.toChar())
            c = readByte()
        }
        return sb.toString()
    }

    fun nextChar(): Char {
        var c = readByte()
        if (c == -1) Helper.EOF()
        return c.toChar()
    }
}

