using System;
using System.Collections.Generic;
using System.Linq;
using System.Diagnostics;
//using mystruct = System.Int64;

public sealed class Solution : Helper
{
    //
    public void __main(int _TCID = 1)
    {
        checked
        {
            //
            readWordString();
            var s = readWordString().ToCharArray();
            var n = s.Length;
            var upb = n - 1;
            //
            var res = new ValueRefPointer<long>();
            res.ValueNullable = n;
            seq(1, upb).TakeWhile(i => countLength(0, i - 1) <= countLength(i, upb)).elect(i =>
              {
                  if (seq(0, i - 1).Select(a => s[a]).SequenceEqual(seq(i, getRight(i, countLength(0, i - 1))).Select(b => s[b])))
                      res.UpdateCompute(1 + i + (n - i - countLength(0, i - 1)), Math.Min);
              });
            writeNumber(res.ValueNullable ?? 1);
            //
        }
        writeLine();
    }
    //
}


// additional plugable library
public partial class Helper
{
    //
    static bool MULTI_TCs = false;
    #region STDIO
#if !DEBUG
    static void Main() { __stdioMain(); }
#endif
    static void __stdioMain()
    {
        Console.SetIn(new System.IO.StreamReader(new System.IO.BufferedStream(Console.OpenStandardInput())));
        Console.SetOut(new System.IO.StreamWriter(new System.IO.BufferedStream(Console.OpenStandardOutput())));
        var cnt = MULTI_TCs ? int.Parse(Console.ReadLine()) : 1;
        for (var i = 1; i <= cnt; i++) new Solution().__main(i);
        Console.Out.Flush();
    }
    // OUTput
    internal string separatorAutoString;
    internal void writeLine() { Console.WriteLine(); }
    internal void writeSeparator() { if (!string.IsNullOrEmpty(separatorAutoString)) { Console.Write(separatorAutoString); } }
    internal void writeText(char c) { Console.Write(c); writeSeparator(); }
    internal void writeText(string s) { Console.Write(s); writeSeparator(); }
    internal void writeNumber(long i64) { Console.Write(i64); writeSeparator(); }
    internal void writeNumber(int i32) { Console.Write(i32); writeSeparator(); }
    internal void writeNumber(double dec) { Console.Write(dec); writeSeparator(); }
    // INput
    static void EOF() { throw new System.IO.EndOfStreamException(); }
    static IEnumerable<char> stream() { while (true) { var iread = Console.Read(); if (iread < 0) break; yield return (char)iread; } }
    static bool isWhitespace(char c) { return c == ' ' || c == '\n' || c == '\r' || c == '\t'; }
    static System.Text.StringBuilder sb = new System.Text.StringBuilder(30);
    internal static string readWordString()
    {
        sb.Clear();
        var iter = stream().SkipWhile(isWhitespace).TakeWhile(c => !isWhitespace(c));
        foreach (var c in iter) sb.Append(c);
        if (sb.Length == 0) EOF(); return sb.ToString();
    }
    internal static long readLong64() { return long.Parse(readWordString()); }
    internal static char readSingleChar() { return stream().SkipWhile(isWhitespace).First(); }
    #endregion
    //
    internal class ValueRefPointer<T> where T : struct
    {
        public T? ValueNullable;
        public ValueRefPointer<T> IfAbsent(Action<ValueRefPointer<T>> init) { if (ValueNullable == null) init(this); return this; }
        public ValueRefPointer<T> UpdateIfAbsent(Func<T> calc) { if (ValueNullable == null) ValueNullable = calc(); return this; }
        public ValueRefPointer<T> UpdateCompute(T other, Func<T, T, T> merge_CHECKED) { var ans = other; if (ValueNullable.HasValue) ans = merge_CHECKED(other, ValueNullable.Value); ValueNullable = ans; return this; }
        public ValueRefPointer<T> UpdateCompute(T? other, Func<T, T, T> merge_CHECKED) { if (other.HasValue) UpdateCompute(other.Value, merge_CHECKED); return this; }
        public ValueRefPointer<T> Swap(ValueRefPointer<T> with) { var temp = ValueNullable; ValueNullable = with.ValueNullable; with.ValueNullable = temp; return this; }
        //TODO switch to implicit cast from ValueRefPointer to T?
        public ValueRefPointer<T> UpdateCompute(ValueRefPointer<T> other, Func<T, T, T> merge_CHECKED) { return UpdateCompute(other.ValueNullable, merge_CHECKED); }
        public override string ToString() { return ValueNullable.ToString(); }
    }
}
